            stack.append(char)
            if not groups:
                groups.append('')  # Start a new group if it's the first opening brace
        elif char == ')':
            if stack:
                stack.pop()
                if stack:
                    groups[-1] += ')'
                else:
                    groups.append(')')
            else:
                groups.append(')')  # Close a group that hasn't been opened

    return groups
```

