    dp = [[[float('inf')] * (k + 1) for _ in range(N)] for _ in range(N)]

    # Helper function to find the minimum path length
    def findMinPath(i, j, l, path):
        if l == k:
            dp[i][j][l].append(path)
            return
        for di, dj in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < N and 0 <= nj < N:
                if grid[ni][nj] not in path:
                    dp[i][j][l].append(path + [grid[ni][nj]])
                    findMinPath(ni, nj, l + 1, path + [grid[ni][nj]])

    # Initialize the first cell
    dp[0][0][0] = [[grid[0][0]]]

    # Fill the DP table
    for l in range(1, k + 1):
        for i in range(N):
            for j in range(N):
                if dp[i][j][l - 1]:
                    for path in dp[i][j][l - 1]:
                        findMinPath(i, j, l, path)

    # Find the minimum path
    min_path = float('inf')
    for i in range(N):
        for j in range(N):
            for path in dp[i][j][k]:
                if sum(path) == min_path:
                    min_path = path
                elif sum(path) < min_path:
                    min_path = path

    return min_path

